from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    """
    Moves n business days (Monday to Friday, not in holidays) from d; n may be negative.
    d itself never counts as one of the n days.
    With n == 0, return d if it is a business day, otherwise the next business day.
    """
    def is_business_day(date_obj: date) -> bool:
        return date_obj.weekday() < 5 and date_obj not in holidays

    if n == 0:
        return d if is_business_day(d) else d + timedelta(days=1)

    if n > 0:
        current_date = d + timedelta(days=1)
        days_counted = 0
        while days_counted < n:
            if is_business_day(current_date):
                days_counted += 1
            current_date += timedelta(days=1)
        return current_date

    else:  # n < 0
        current_date = d - timedelta(days=1)
        days_counted = 0
        while days_counted < abs(n):
            if is_business_day(current_date):
                days_counted += 1
            current_date -= timedelta(days=1)
        return current_date
