import re

def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.split('\n')
    ini_sections = {}
    current_section = None

    for line in lines:
        line = line.strip()
        if not line or line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            ini_sections[current_section] = {}
            continue

        if current_section:
            if '=' in line:
                k, v = line.split('=', 1)
                ini_sections[current_section][k.strip()] = v.strip()

    if section not in ini_sections:
        raise KeyError(f"Section '{section}' not found in the INI text.")
    if key not in ini_sections[section]:
        raise KeyError(f"Key '{key}' not found in section '[ {section} ]'.")

    new_lines = []
    key_to_find = key
    value_to_set = value
    key_pattern = re.compile(rf"^\s*{re.escape(key_to_find)}\s*=\s*")

    for line in lines:
        stripped_line = line.strip()

        # Check for section headers
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            if stripped_line[1:-1] == section:
                # Check if this is the line to change (or is a comment/blank in the target section)

                # Check if this line contains the target key assignment
                if key_pattern.match(line):
                    # Reconstruct the line with the new value, maintaining leading whitespace if present
                    leading_whitespace = line[:line.find(key_to_find)]
                    new_line = f"{leading_whitespace}{key_to_find} = {value_to_set}"
                    new_lines.append(new_line)
                    continue

                # If it's the section header line itself, return it as is, unless it's the line we are replacing (which is not how ini works, keys are inside)
                new_lines.append(line)
                continue

        # Check for key=value pairs within the target section
        if current_section == section and '=' in line:
            k, v = line.split('=', 1)
            if k.strip() == key_to_find:
                # Found the key, replace it while preserving original leading/trailing spaces if possible
                leading_ws = line[:line.find(k)]
                new_line = f"{leading_ws}{key_to_find} = {value_to_set}"
                new_lines.append(new_line)
                continue

        # Keep all other lines exactly as they were
        new_lines.append(line)

    return '\n'.join(new_lines)
