def deep_merge(base: dict, override: dict) -> dict:
    """
    Returns a new dict that is the deep merge of base and override.
    Keys in override win, dict values are merged recursively,
    lists and other values are replaced, and None deletes the key.
    """
    result = base.copy()

    for key, override_value in override.items():
        if override_value is None:
            # Deletes the key
            result.pop(key, None)
            continue

        if key in result:
            base_value = result[key]

            if isinstance(base_value, dict) and isinstance(override_value, dict):
                # Recursive merge for dictionaries
                result[key] = deep_merge(base_value, override_value)
            else:
                # Replacement for lists, primitives, or when types don't allow recursion
                # We must ensure the new value is a deep copy if it's mutable (dict/list)
                if isinstance(override_value, dict):
                    result[key] = {k: deep_merge(v, {}) if isinstance(v, dict) else v.copy() for k, v in override_value.items()}
                elif isinstance(override_value, list):
                    result[key] = [item for item in override_value] # Shallow copy of list is usually enough unless items are mutable and need deep copies
                else:
                    result[key] = override_value
        else:
            # Key only exists in override, must deep copy if mutable
            if isinstance(override_value, dict):
                result[key] = {k: deep_merge(v, {}) if isinstance(v, dict) else v.copy() for k, v in override_value.items()}
            elif isinstance(override_value, list):
                result[key] = [item for item in override_value] # Shallow copy of list
            else:
                result[key] = override_value

    # Final deep copy to ensure no shared references with base/override inputs, 
    # especially for top-level structures that were only copied shallowly initially.
    # We iterate through the final result and recursively clone mutable objects.
    def deep_copy_recursive(obj):
        if isinstance(obj, dict):
            return {k: deep_copy_recursive(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy_recursive(item) for item in obj]
        elif isinstance(obj, set):
            return {deep_copy_recursive(item) for item in obj}
        return obj

    return deep_copy_recursive(result)
