import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    """
    Tells whether ip is inside any of the CIDR networks (IPv4 or IPv6).
    An IPv4-mapped IPv6 address such as '::ffff:10.0.0.5' counts as the IPv4 address it carries.
    A network may have host bits set ('10.0.0.1/8' means 10.0.0.0/8).
    An invalid ip returns False; an invalid network raises ValueError.
    """
    try:
        ip_obj = ipaddress.ip_address(ip)
    except ValueError:
        return False

    for network_str in networks:
        try:
            network = ipaddress.ip_network(network_str)
        except ValueError:
            raise ValueError(f"Invalid network provided: {network_str}")

        if ip_obj in network:
            # Handle IPv4-mapped IPv6 addresses explicitly for IPv4 matching if the network is strictly IPv4
            if ip_obj.version == 6 and network.version == 4:
                # Check if the IPv6 address is an IPv4-mapped address and its IPv4 part is in the IPv4 network
                if ip_obj.is_unspecified or ip_obj.is_loopback:
                    continue

                # Extract the IPv4 address from the IPv6 address if it's mapped
                try:
                    if ip_obj.version == 6 and ip_obj.compressed == ip_obj.compressed[:32] + ':' + ip_obj.packed[0:4].hex():
                        ipv4_part = ipaddress.IPv4Address(ip_obj.packed[0:4])
                        if ipv4_part in network:
                            return True
                except AttributeError:
                    # Not a standard IPv4-mapped IPv6, ignore this specific check
                    pass

            elif ip_obj.version == network.version:
                return True

            # Special case: IPv4-mapped IPv6 address matching an IPv6 network, even if the network is in 'host' mode
            if ip_obj.version == 6 and network.version == 6:
                if ip_obj.is_ipv4_mapped:
                    # If the network definition includes host bits, we check if the host bits are zero for the host part
                    # However, ipaddress.ip_network correctly handles the network range regardless of host bits set in the string
                    # So, a simple membership check should suffice if the address is valid.
                    return ip_obj in network

        except ValueError:
            # This case is caught during network parsing and re-raised per requirements
            raise

    return False
