def remove_Occ(s: str, char: str) -> str:
    if not s:
        return s

    # Remove the first occurrence
    try:
        first_index = s.index(char)
        s_modified = s[:first_index] + s[first_index+1:]
    except ValueError:
        # Character not found, return original string
        return s

    # Remove the last occurrence from the modified string
    try:
        last_index = s_modified.rindex(char)
        result = s_modified[:last_index] + s_modified[last_index+1:]
    except ValueError:
        # If the character was only present once, it's already removed, return the current state
        result = s_modified

    return result
