def compact(n: int) -> str:
    """Formats a non-negative integer in Brazilian short form with at most one decimal place and a decimal comma."""
    if n == 0:
        return "0"

    units = ['', 'mil', 'mi', 'bi']
    groups = [range(1, 1000), range(1000, 1000000), range(1000000, 1000000000), range(1000000000, float('inf'))]
    powers = [1, 3, 6, 9]

    if n < 1000:
        return str(n)

    # Determine the correct scale
    scale_index = 0
    while n >= 10**(powers[scale_index + 1]) and scale_index + 1 < len(units):
        scale_index += 1

    # Scale and round
    value = n / (10**powers[scale_index])
    rounded_value = round(value * 10) / 10.0

    # Handle the rounding edge case (e.g., 999950 -> 1 mi, not 1000 mil)
    # If rounding pushed it to the next unit boundary significantly, re-evaluate scale
    if abs(rounded_value - round(rounded_value)) < 0.001 and rounded_value >= 1000 and scale_index + 1 < len(units):
        # Check if the next unit is better
        next_scale_index = scale_index + 1
        next_value = n / (10**powers[next_scale_index])
        next_rounded_value = round(next_value * 10) / 10.0
        if next_rounded_value < 10 and next_rounded_value >= 1:
             rounded_value = next_rounded_value
             scale_index = next_scale_index

    if rounded_value == 1.0 and scale_index > 0 and n < 10**(powers[scale_index]):
        # This handles cases where rounding might bring it down unexpectedly,
        # but the initial scale determination should usually prevent this unless very close to boundary
        pass


    # Formatting
    if abs(rounded_value - round(rounded_value)) < 1e-9:
        formatted_value = str(int(rounded_value))
    else:
        formatted_value = f"{rounded_value:.1f}".rstrip('0').rstrip('.')

    if formatted_value == '0' and scale_index > 0:
        return f"1 {units[scale_index]}" # Should not happen with positive n

    if formatted_value == "" or formatted_value == "-": # If rounding resulted in 0.0 and we need to keep the unit
        return f"1 {units[scale_index]}"

    if formatted_value == '0.0':
        formatted_value = '0' # Should be handled by initial checks, but as a safeguard

    if formatted_value.endswith('.0'):
        formatted_value = formatted_value[:-2]

    if scale_index == 0:
        return str(n)

    if len(formatted_value.split('.')[-1]) == 0 and '.' in formatted_value:
        # This handles the case where rounding resulted in an integer but still has a decimal point from f-string formatting, e.g., "1.0" becoming "1."
        formatted_value = formatted_value.split('.')[0]


    if scale_index == 0:
        return str(n)

    if scale_index > 0 and formatted_value == '0':
        # This implies the original number was extremely close to 0 but we are in a higher scale
        # Given n >= 1000, this should not occur.
        pass

    if formatted_value == '0' and n >= 1:
        # If somehow the rounding resulted in 0 for a positive number, use the smallest representable unit (1)
        formatted_value = '1'


    return f"{formatted_value} {units[scale_index]}"
