def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines()
    in_target_section = False
    new_lines = []
    target_line_index = -1

    for i, line in enumerate(lines):
        stripped_line = line.strip()

        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            in_target_section = (current_section == section)
            if in_target_section:
                continue  # Don't process the section header line yet

        if in_target_section and not stripped_line.startswith(';') and not stripped_line.startswith('#') and '=' in stripped_line:
            # Check if the key matches exactly, ignoring spaces around '='
            current_key_part = stripped_line.split('=', 1)[0].strip()
            if current_key_part == key:
                target_line_index = i
                break
        elif in_target_section and not (stripped_line.startswith(';') or stripped_line.startswith('#') or not stripped_line):
            # If we are in the section but haven't found the key yet, we might need to continue iterating
            pass

        new_lines.append(line)

    if target_line_index == -1:
        # Re-scan to check for section existence even if key is missing (to raise error)
        section_found = False
        for i, line in enumerate(lines):
            stripped_line = line.strip()
            if stripped_line.startswith('[') and stripped_line.endswith(']'):
                current_section = stripped_line[1:-1].strip()
                if current_section == section:
                    section_found = True
                    break
        if not section_found:
            raise KeyError(f"Section [{section}] not found in the INI text.")
        else:
            # Section exists, but key does not
            raise KeyError(f"Key '{key}' not found in section [{section}].")

    # Perform replacement
    new_lines[target_line_index] = f"{key} = {value}"
    return "\n".join(new_lines)
