                current_best = latest_records_map[record_key]

                # Compare times
                if dt > current_best['dt']:
                    # New record is strictly later
                    latest_records_map[record_key] = {
                        'record': record,
                        'dt': dt,
                        'index': i
                    }
                elif dt == current_best['dt']:
                    # Tie: keep the one that comes later in the list (higher index)
                    if i > current_best['index']:
                        latest_records_map[record_key] = {
                            'record': record,
                            'dt': dt,
                            'index': i
                        }

    result = []
    # Construct the final list maintaining the order of first appearance
    for k in key_order:
        if k in latest_records_map:
            result.append(latest_records_map[k]['record'])

    return result
