from ipaddress import ip_address, ip_network, AddressValueError, NetmaskValueError

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        target_ip = ip_address(ip)
    except ValueError:
        return False

    for network_str in networks:
        try:
            network = ip_network(network_str, strict=False)
        except (ValueError, AddressValueError, NetmaskValueError) as e:
            raise ValueError(f"Invalid network specified: {network_str}") from e

        # Handle IPv4-mapped IPv6 addresses
        if target_ip.version == 6 and str(ip_address(target_ip)) != str(target_ip):
            # Check if it's an IPv4-mapped IPv6 address
            try:
                ipv4_mapped_ip = ip_address(target_ip.packed[8:])
                if network.version == 4:
                    # Convert the IPv4 part to an IPv6 address representation for comparison, if necessary,
                    # but the easiest way is to check if the IPv4 address is in the IPv4 network
                    ipv4_addr = ipv4_mapped_ip
                    if ipv4_addr in ip_network(network_str, strict=False):
                        return True
            except IndexError:
                # Not an IPv4-mapped IPv6 address that can be easily interpreted
                pass

        if target_ip in network:
            return True

    return False
